/**
 * Dashboard Sparkline Renderer
 *
 * Renders mini sparkline charts for queue trends using Chart.js
 *
 * @package ContactInbox\Dashboard\JS
 */

const sparklineCharts = {};

const DashboardSparkline = {
    /**
     * Render sparkline chart for queue type
     */
    renderSparkline(canvasId, data, color) {
        const el = document.getElementById(canvasId);
        if (!el) return;
        if (!data || !Array.isArray(data) || data.length === 0) return;
        if (typeof Chart === 'undefined') return;

        // Destroy previous instance to prevent size creep and memory leaks
        if (sparklineCharts[canvasId]) {
            sparklineCharts[canvasId].destroy();
            sparklineCharts[canvasId] = null;
        }

        // Respect any template-provided height while locking attribute and style to prevent creep
        const providedHeight = parseInt(el.getAttribute('height'), 10);
        const fixedHeight = Number.isFinite(providedHeight) ? providedHeight : 40;
        el.height = fixedHeight;
        el.style.height = `${fixedHeight}px`;
        el.style.maxHeight = `${fixedHeight}px`;

        const labels = data.map(item => (item.date || '').slice(5));
        const values = data.map(item => parseInt(item.count || 0, 10));

        sparklineCharts[canvasId] = new Chart(el.getContext('2d'), {
            type: 'line',
            data: {
                labels,
                datasets: [{
                    data: values,
                    borderColor: color,
                    backgroundColor: 'rgba(0,0,0,0)',
                    borderWidth: 2,
                    tension: 0.35,
                    pointRadius: 0,
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false },
                    tooltip: { enabled: false },
                },
                scales: {
                    x: {
                        display: false,
                        grid: {
                            display: false,
                        },
                        border: { display: false }
                    },
                    y: {
                        display: false,
                        grid: {
                            display: false,
                        },
                        border: { display: false }
                    },
                }
            }
        });
    },

    /**
     * Render all queue type sparklines
     */
    renderAll(trendData) {
        if (!trendData || typeof trendData !== 'object') return;

        this.renderSparkline('spark-email-queue', trendData.email || [], '#f0ad4e');
        this.renderSparkline('spark-crm-queue', trendData.crm || [], '#2196F3');
    },

    /**
     * Initialize sparklines when DOM is ready and data is available
     */
    init() {
        if (typeof contactinSparklineTrends !== 'undefined') {
            this.renderAll(contactinSparklineTrends);
        }
    }
};

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    DashboardSparkline.init();
});
